// Capability is generated by the harness for one running turn. Caller cannot choose a parent.
export function createFamilyHandler(capabilities, family) {
  return async (req, res) => {
    const reply = (code, data) => {res.writeHead(code, {'content-type':'application/json'});res.end(JSON.stringify(data))}
    const token = req.headers.authorization?.replace(/^Bearer /, '')
    const parent = capabilities.get(token)
    if (!parent) {reply(403, {error:'Invalid or expired turn capability'});return}
    let raw=''
    try {
      for await (const chunk of req) {raw+=chunk; if(Buffer.byteLength(raw)>20000) {reply(413,{error:'Request too large'});return}}
      const {name, arguments:args={}}=JSON.parse(raw)
      if (name==='list_agents') reply(200, family.list(parent))
      else if (name==='spawn_agent') reply(200, await family.spawn(parent,args))
      else if (name==='message_agent') reply(200, await family.message(parent,args.room_id,args.prompt))
      else reply(400,{error:'Unknown agent tool'})
    } catch(e) {reply(400,{error:e.message})}
  }
}
